    result = ''
    for char in s:
        result = char + result
    return result

def method4_while_loop(s):
    result = ''
    i = len(s) - 1
    while i >= 0:
        result += s[i]
        i -= 1
    return result

def method5_recursive(s):
    if len(s) == 0:
        return s
    return method5_recursive(s[1:]) + s[0]

def method6_list_comprehension(s):
    return ''.join([s[i] for i in range(len(s)-1, -1, -1)])

def method7_stack(s):
    stack = list(s)
    result = ''
    while stack:
        result += stack.pop()
    return result

def method8_bytearray(s):
    return bytearray(s, 'utf-8')[::-1].decode('utf-8')

def method9_enumerate(s):
    result = [''] * len(s)
    for i, char in enumerate(s):
        result[len(s)-1-i] = char
    return ''.join(result)

def method10_reduce(s):
    from functools import reduce
    return reduce(lambda x, y: y + x, s)

def method11_two_pointer(s):
    s_list = list(s)
    left, right = 0, len(s_list) - 1
    while left < right:
        s_list[left], s_list[right] = s_list[right], s_list[left]
        left += 1
        right -= 1
    return ''.join(s_list)

# Collect all methods
methods = [
    ("Method 1: Slicing", method1_slicing),
    ("Method 2: reversed() + join()", method2_reversed_join),
    ("Method 3: For loop", method3_for_loop),
    ("Method 4: While loop", method4_while_loop),
    ("Method 5: Recursive", method5_recursive),
    ("Method 6: List comprehension", method6_list_comprehension),
    ("Method 7: Stack (pop)", method7_stack),
    ("Method 8: Bytearray", method8_bytearray),
    ("Method 9: Enumerate", method9_enumerate),
    ("Method 10: Reduce", method10_reduce),
    ("Method 11: Two-pointer swap", method11_two_pointer)
]

# Execute all methods
