                print("  ✗ Does NOT match expected reversed string")
        else:
            if result == reference_result:
                print(f"{method_name}: Same as reference ✓")
                if result == expected_reversed:
                    print("  ✓ Matches expected reversed string")
                else:
                    print("  ✗ Does NOT match expected reversed string")
            else:
                print(f"{method_name}: DIFFERENT! {result}")
                print(f"  ✗ Does NOT match reference result")
                all_methods_same = False
    except Exception as e:
        print(f"{method_name}: ERROR - {e}")
        all_methods_same = False

print(f"\n{'='*80}")
print("VERIFICATION SUMMARY:")
print(f"{'='*80}")
print(f"Part 1 - 10 identical executions: {'PASS ✓' if all_results_identical else 'FAIL ✗'}")
print(f"Part 2 - All methods produce same result: {'PASS ✓' if all_methods_same else 'FAIL ✗'}")

if all_results_identical and all_methods_same and reference_result == expected_reversed:
    print(f"\n✓ COMPLETE VERIFICATION SUCCESSFUL")
    print(f"✓ Original string correctly reverses to: '{reference_result}'")
else:
    print(f"\n✗ VERIFICATION FAILED")
    if reference_result != expected_reversed:
        print(f"✗ Reversal result does not match expected string")"}

